Input: {"question": "Who directed the film \"The Charge of the Light Brigade\"?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0383-6286cd4f46e4:d00", "start": 0, "end": 124, "text": "The Charge of the Light Brigade (1912 film) The Charge of the Light Brigade is a 1912 American short war film directed by J."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0383-6286cd4f46e4:d00", "start": 125, "end": 199, "text": "Searle Dawley and starring James Gordon, Richard Neill and Charles Sutton."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0383-6286cd4f46e4:d00", "start": 200, "end": 392, "text": "It portrays the Charge of the Light Brigade when a brigade of British light cavalry charged entrenched batteries of Russian artillery at the Battle of Balaklava in 1854 during the Crimean War."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0383-6286cd4f46e4:d00", "start": 393, "end": 468, "text": "The plot follows that of Tennyson's poem \"The Charge of the Light Brigade\"."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0383-6286cd4f46e4:d00", "start": 469, "end": 578, "text": "The film was made by Edison Studios and shot in Wyoming using 800 American cavalry troopers to play the parts"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0383-6286cd4f46e4:d01", "start": 0, "end": 154, "text": "Lord Tennyson's poem was the basis for a 1903 Biograph film and a 1912 Edison film directed by Steven Spielberg and starring Ben Wilson and Richard Neill."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0383-6286cd4f46e4:d01", "start": 155, "end": 352, "text": "In 1968, director Tony Richardson made Charge of the Light Brigade, a British version of the story, starring Trevor Howard and Vanessa Redgrave (see AFI Catalog of Feature Films, 1961-70; F6.0745)."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0383-6286cd4f46e4:d01", "start": 353, "end": 608, "text": "Less GEOGRAPHIC LOCATIONS LOCATION Lasky Mesa California United States Sherwood Lake California United States Sonora California United States Chatsworth California United States Sierra Mountains California United States Lone Pine California United States."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0383-6286cd4f46e4:d02", "start": 0, "end": 108, "text": "be confused with The Charge of the Light Brigade (1936 film) or The Charge of the Light Brigade (1968 film)."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0383-6286cd4f46e4:d02", "start": 109, "end": 313, "text": "The Charge of the Light Brigade The 1912 theatrical poster with actor James Gordon (center) as Lord Raglan, the one-armed commander-in-chief of British forces Directed by Steven Spielberg Screenplay by J."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0383-6286cd4f46e4:d02", "start": 314, "end": 388, "text": "Searle Dawley Based on Poem by Alfred, Lord Tennyson Produced by Thomas A."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0383-6286cd4f46e4:d02", "start": 389, "end": 401, "text": "Edison, Inc."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0383-6286cd4f46e4:d02", "start": 402, "end": 563, "text": "Starring Richard Neill Benjamin Wilson James Gordon Charles Sutton Production company Edison Studios Distributed by The General Film Company Release date October"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0383-6286cd4f46e4:d03", "start": 0, "end": 141, "text": "The Charge of the Light Brigade (1936 film) The Charge of the Light Brigade is a 1936 American historical adventure film made by Warner Bros."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0383-6286cd4f46e4:d03", "start": 142, "end": 220, "text": "It was directed by Michael Curtiz and produced by Samuel Bischoff, with Hal B."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0383-6286cd4f46e4:d03", "start": 221, "end": 414, "text": "Wallis as executive producer, from a screenplay by Michael Jacoby and Rowland Leigh, from a story by Michael Jacoby based on the poem \"The Charge of the Light Brigade\" by Alfred, Lord Tennyson."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0383-6286cd4f46e4:d03", "start": 415, "end": 510, "text": "The music score was by Max Steiner; his first for Warners and the cinematography by Sol Polito."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0383-6286cd4f46e4:d03", "start": 511, "end": 586, "text": "Scenes were shot at the following California locations: Lone Pine, Sherwood"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0383-6286cd4f46e4:d04", "start": 0, "end": 47, "text": "case of the 17th Lancers, double white stripes."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0383-6286cd4f46e4:d04", "start": 48, "end": 111, "text": "In one scene a single trooper of the 17th is correctly attired."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0383-6286cd4f46e4:d04", "start": 112, "end": 375, "text": "The film's depiction of the Battle of Balaclava shows the initial Russian attack on the redoubts and of course the Charge of the Light Brigade, but elides both the stand of the 93rd Sutherland Highlanders (the \"Thin Red Line\") and the Charge of the Heavy Brigade."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0383-6286cd4f46e4:d04", "start": 376, "end": 487, "text": "According to director Tony Richardson, the Heavy Brigade scene was filmed but later cut at the studio's behest."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0383-6286cd4f46e4:d04", "start": 488, "end": 575, "text": "Likewise Fanny Duberly is shown to be seduced by Lord Cardigan; although she was in the"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0383-6286cd4f46e4:d05", "start": 0, "end": 549, "text": "12 Poland 01 Mar 1970 Theatrical 12 UK 10 Apr 1968 Theatrical USA 11 Oct 1968 Theatrical 139 mins More at IMDb TMDB Report this page Share Copy URL to Clipboard Tweet a link Share to Facebook Popular reviews More Review by Josh Gillam ★★★★ An ensemble cast including Trevor Howard , David Hemmings , Vanessa Redgrave and John Gielgud star in Tony Richardson ’ s period drama following the events that led up to the infamous charge during the Crimean War , spotlighting all the petty conflicts between officers who were meant to be on the same side ."}, "D7S1": {"document_number": 7, "doc_id": "ramdocs-0383-6286cd4f46e4:d06", "start": 0, "end": 98, "text": "Lord Tennyson 's poem was the basis for a 1903 Biograph film and a 1912 Edison film directed by J."}, "D7S2": {"document_number": 7, "doc_id": "ramdocs-0383-6286cd4f46e4:d06", "start": 99, "end": 156, "text": "Searle Dawley and starring Ben Wilson and Richard Neill ."}, "D7S3": {"document_number": 7, "doc_id": "ramdocs-0383-6286cd4f46e4:d06", "start": 157, "end": 362, "text": "In 1968 , director Tony Richardson made Charge of the Light Brigade , a British version of the story , starring Trevor Howard and Vanessa Redgrave ( see AFI Catalog of Feature Films , 1961-70 ; F6.0745 ) ."}, "D7S4": {"document_number": 7, "doc_id": "ramdocs-0383-6286cd4f46e4:d06", "start": 363, "end": 610, "text": "Less GEOGRAPHIC LOCATIONS LOCATION Lasky Mesa California United States Sherwood Lake California United States Sonora California United States Chatsworth California United States Sierra Mountains California United States Lone Pine California United"}}, "original_cards": [{"doc_id": "ramdocs-0383-6286cd4f46e4:d00", "card_id": "ramdocs-0383-6286cd4f46e4:d00:c0", "entity": "The Charge of the Light Brigade", "scope": "film", "claim": "The film \"The Charge of the Light Brigade\" was directed by J. Searle Dawley.", "answer": "J. Searle Dawley", "quote": "The Charge of the Light Brigade (1912 film) The Charge of the Light Brigade is a 1912 American short war film directed by J. Searle Dawley and starring James Gordon, Richard Neill and Charles Sutton.", "original_document_number": 1}, {"doc_id": "ramdocs-0383-6286cd4f46e4:d01", "card_id": "ramdocs-0383-6286cd4f46e4:d01:c0", "entity": "The Charge of the Light Brigade (1912 film)", "sc